/**
 * The page for a query and its results (`design/archetypes/search-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  claimSlot,
  createDerived,
  createKept,
  resolveSlot,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/search-page.module.css'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState'
import Inline from '../layout/Inline'
import PageHeader from '../structure/PageHeader'

export interface SearchPageProps {
  /**
   * Vocabulary controls, including the page's one primary action.
   */
  actions?: JSX.Element
  /**
   * Groups of results, each a Heading, a List and a CursorPagination. None before a query.
   */
  children?: JSX.Element
  description?: string
  /**
   * The query found nothing: the results region holds the empty state.
   */
  empty?: boolean
  /**
   * The empty state, required so the page always says what it shows when a query finds nothing.
   */
  emptyState: EmptyStateProps
  /**
   * A FilterBar, or `sm` controls, under the field.
   */
  filters?: JSX.Element
  /**
   * Makes the landmark a real `<form>`, so Enter in the field submits. Without it the
   * application searches as the reader types.
   */
  onSubmit?: () => void
  /**
   * A search is running: the results region is busy, and the last results stay in it.
   */
  pending?: boolean
  /**
   * The query field: a SearchInput, or a FormField with an Input whose `trailing` is a submit
   * Button.
   */
  search: JSX.Element
  /**
   * The search landmark's name. A shell often has a search of its own, and two landmarks of one
   * kind are told apart only by their names.
   */
  searchLabel: string
  title: string
}

/** The page for a query and its results. */
export default function SearchPage(given: SearchPageProps): JSX.Element {
  const props = mergeProps(
    { empty: false, pending: false } as Defaults<SearchPageProps, 'empty' | 'pending'>,
    claimSlot(given),
  )
  return scope(() => {
    const emptyStateKept = createKept(() => props.emptyState)
    const actionsSlot = resolveSlot(() => props.actions)
    const filtersSlot = resolveSlot(() => props.filters)
    const submit = createDerived(() => (event: Event) => {
      event.preventDefault()
      props.onSubmit?.()
    })
    return (
      <div
        class={styles.page}
        data-empty={props.empty ? '' : undefined}
        data-pending={props.pending ? '' : undefined}
        data-member="search-page"
      >
        <PageHeader
          title={props.title}
          description={props.description}
          actions={actionsSlot.filled() ? actionsSlot() : undefined}
        />
        {props.onSubmit !== undefined ? (
          <form
            class={styles.search}
            role="search"
            aria-label={props.searchLabel}
            data-search-page-part="search"
            novalidate={true}
            onsubmit={($event: SubmitEvent) => submit.value($event)}
          >
            {props.search}
            {filtersSlot.filled() ? (
              <Inline gap={3} wrap={true}>
                {filtersSlot()}
              </Inline>
            ) : null}
          </form>
        ) : (
          <div
            class={styles.search}
            role="search"
            aria-label={props.searchLabel}
            data-search-page-part="search"
          >
            {props.search}
            {filtersSlot.filled() ? (
              <Inline gap={3} wrap={true}>
                {filtersSlot()}
              </Inline>
            ) : null}
          </div>
        )}
        {/* results */}
        <div
          class={styles.results}
          aria-busy={props.pending ? true : undefined}
          data-search-page-part="results"
        >
          {props.empty ? (
            <EmptyState
              icon={emptyStateKept.value.icon}
              title={emptyStateKept.value.title}
              description={emptyStateKept.value.description}
              action={
                emptyStateKept.value.action !== undefined ? emptyStateKept.value.action : undefined
              }
              secondaryAction={
                emptyStateKept.value.secondaryAction !== undefined
                  ? emptyStateKept.value.secondaryAction
                  : undefined
              }
            />
          ) : (
            props.children
          )}
        </div>
      </div>
    )
  })
}
